module OLED_ShowFont(
	sys_clk,
	rst_n,
	ShowFont_req,
	write_done,
	fontdata,
	ShowFont_Data,
	font_row,
	ShowFont_finish,
	font_index,
	ShowFont_index_after);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	input ShowFont_req;
	input write_done;
	input [7:0] fontdata;
	output [23:0] ShowFont_Data;
	output font_row;
	output ShowFont_finish;
	output [5:0] font_index;
	output [8:0] ShowFont_index_after;

	wire sys_clk;
	wire rst_n;
	wire ShowFont_req;
	wire write_done;
	wire [7:0] fontdata;
	wire [23:0] ShowFont_Data;
	reg font_row;
	wire ShowFont_finish;
	reg [5:0] font_index;
	wire [8:0] ShowFont_index_after;

	//----Code starts here: integrated by Robei-----
	wire onefont_finish;
	
	reg		font_size; //1 :16*16   0 : 8*16
	reg[7:0]		show_x;
	reg[3:0]		show_y;
	reg[8:0]	   showfont_index;
	reg[23:0]	showfont_data_reg;
	
	assign onefont_finish = ((showfont_index == (4'd10 + 4'd8 * font_size)) && (font_row == 1'b1) && write_done == 1'b1) ? 1'b1 : 1'b0;
	assign ShowFont_finish = (onefont_finish == 1'b1 && font_index == 6'd1) ? 1'b1 : 1'b0;
	assign ShowFont_Data = showfont_data_reg;
	assign ShowFont_index_after = showfont_index - 'd3;
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			showfont_index <=9'd0;
		else if(onefont_finish == 1'b1)
			showfont_index <= 9'd0;
		else if(font_size == 1'd0 && showfont_index == 9'd10 && write_done == 1'b1)
			showfont_index <= 9'd0;
	    
		else if(font_size == 1'd1 && showfont_index == 9'd18 && write_done == 1'b1)
			showfont_index <= 9'd0;
		
		else if(write_done == 1'b1 && ShowFont_req == 1'b1)
			showfont_index <= showfont_index + 1'b1;
		else
			showfont_index <= showfont_index;
	end
	
	always@(*)
	begin
		case(showfont_index)
		9'd0:	showfont_data_reg <= {8'h78,8'h00,8'hB0 + show_y + font_row};
		9'd1:  showfont_data_reg <= {8'h78,8'h00,8'h00 + show_x[3:0]};
		9'd2:  showfont_data_reg <= {8'h78,8'h00,8'h10 + show_x[7:4]};
		default:	showfont_data_reg <= {8'h78,8'h40,fontdata}; //fontdata
		endcase
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			font_row <= 1'b0;
		else if(onefont_finish == 1'b1)
			font_row <= 1'b0;
		else if(font_size == 1'd0 && showfont_index == 9'd10 && write_done == 1'b1)
			font_row <= 1'b1;
		else if(font_size == 1'd1 && showfont_index == 9'd18 && write_done == 1'b1)
			font_row <= 1'b1;
		else
			font_row <= font_row;
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			font_size <= 1'd0;
	    else if(font_index >= 6'd8 && font_index <= 6'd11)
			font_size <= 1'b1;
	    else if(font_index == 6'd13||font_index == 6'd17||font_index == 6'd18)
	        font_size <= 1'b1;
	    else
			font_size <= 1'b0;
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			font_index <= 6'd0;
		else if(ShowFont_finish == 1'b1)
			font_index <=6'd0;
		else if(onefont_finish == 1'b1)
			font_index <= font_index + 1'b1;
		else
			font_index <= font_index;
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)   
		begin
			show_x <= 8'd10;                                                      //C
			show_y <= 4'd0;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd0)  //I
		begin
			show_x <= 8'd18;
			show_y <= 4'd0;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd1)  //C
		begin
			show_x <= 8'd26;
			show_y <= 4'd0;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd2)  //C
		begin
			show_x <= 8'd34;
			show_y <= 4'd0;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd3)  //5
		begin
			show_x <= 8'd42;
			show_y <= 4'd0;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd4)  //5
		begin
			show_x <= 8'd50;
			show_y <= 4'd0;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd5)	//3
		begin
			show_x <= 8'd58;
			show_y <= 4'd0;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd6)	 //6
		begin
			show_x <= 8'd66;
			show_y <= 4'd0;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd7)	 //温
		begin
			show_x <= 8'd10;
			show_y <= 4'd2;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd8)	  //度
		begin
			show_x <= 8'd26;
			show_y <= 4'd2;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd9)	  //湿
		begin
			show_x <= 8'd10;
			show_y <= 4'd4;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd10)	  //度
		begin
			show_x <= 8'd26;
			show_y <= 4'd4;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd11)	  //.
		begin
			show_x <= 8'd70;
			show_y <= 4'd2;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd12)	  //℃
		begin
			show_x <= 8'd100;
			show_y <= 4'd2;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd13)	   //R
		begin
			show_x <= 8'd100;
			show_y <= 4'd4;
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd14)	   //H
		begin
			show_x <= 8'd108;
			show_y <= 4'd4;	
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd15)	    //.
		begin
			show_x <= 8'd70;
			show_y <= 4'd4;	
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd16)	    //光
		begin
			show_x <= 8'd10;
			show_y <= 4'd6;	
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd17)	   //照
		begin
			show_x <= 8'd26;
			show_y <= 4'd6;	
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd18)	    //l
		begin
			show_x <= 8'd100;
			show_y <= 4'd6;	
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd19)	   //u
		begin
			show_x <= 8'd108;
			show_y <= 4'd6;	
		end
		else if(onefont_finish == 1'b1 && font_index == 6'd20)	    //x
		begin
			show_x <= 8'd116;
			show_y <= 4'd6;	
		end
		else
		begin
			show_x <= show_x;
			show_y <= show_y;
		end
	
	end
	
	
	
endmodule    //OLED_ShowFont

